import{_ as i,o as d,c as e,a4 as a}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"MyBilibili 面试话术","description":"","frontmatter":{"title":"MyBilibili 面试话术","date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/mybilibili-interview.md","filePath":"posts/mybilibili-interview.md"}'),r={name:"posts/mybilibili-interview.md"};function l(o,t,s,h,n,b){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="mybilibili-面试话术" tabindex="-1">MyBilibili 面试话术 <a class="header-anchor" href="#mybilibili-面试话术" aria-label="Permalink to &quot;MyBilibili 面试话术&quot;">​</a></h1><h2 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h2><blockquote><p>&quot;架构设计采用 Go 胖二进制 + 本地 SQLite 缓存 + PG 归档 + Redis 写缓冲的混合方案。读走本地 mmap，~0.01ms，扛 99% 请求；写走 Redis，异步刷 PG，~0.5ms 返回。支持从小到一台盒子到大到一百台机器的水平扩展，不换架构不改代码。部署在自有设备上，月费 100 元电费，同等云配置约 20000 元/月。&quot;</p></blockquote><h2 id="面试官可能问的" tabindex="-1">面试官可能问的 <a class="header-anchor" href="#面试官可能问的" aria-label="Permalink to &quot;面试官可能问的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>回答</th></tr></thead><tbody><tr><td>为什么不用 ES？</td><td>PG tsvector 全文检索够用，不需要 ES 的重量</td></tr><tr><td>为什么不用 MongoDB？</td><td>PG JSONB 功能一样，省一个组件</td></tr><tr><td>数据一致性怎么保证？</td><td>强一致走 PG 事务，最终一致走 Redis → PG</td></tr><tr><td>SQLite 写入瓶颈怎么办？</td><td>SQLite 只做只读缓存，写走 Redis → PG</td></tr><tr><td>水平扩展怎么做？</td><td>Traefik 路由 + 粘性策略，加实例就行</td></tr><tr><td>盒子硬件太弱怎么办？</td><td>业务无状态，扩到其他盒子或手机</td></tr><tr><td>PG 挂了怎么办？</td><td>读走 SQLite 本地缓存，写暂存 Redis，恢复后同步</td></tr></tbody></table><h2 id="与传统架构对比" tabindex="-1">与传统架构对比 <a class="header-anchor" href="#与传统架构对比" aria-label="Permalink to &quot;与传统架构对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的方案</th><th>传统方案</th><th>面试官评价</th></tr></thead><tbody><tr><td>每个组件讲得出为什么选它</td><td>别人用我也用</td><td>有深度，不是照着教程搭</td></tr><tr><td>知道每个组件的边界和局限</td><td>以为 ES 是万能的</td><td>有实战经验</td></tr><tr><td>能讲清楚取舍和成本</td><td>只讲功能不讲成本</td><td>有架构思维</td></tr><tr><td>从性能到成本到运维全链路</td><td>只关心功能实现</td><td>有全局视野</td></tr></tbody></table><h2 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to &quot;技术亮点&quot;">​</a></h2><ol><li>PG 一库三用：关系表 + JSONB 文档 + 全文检索，替代 MySQL + MongoDB + ES</li><li>SQLite 本地缓存：mmap 零拷贝，~0.01ms，扛 99% 读流量</li><li>Redis 写缓冲：先写 Redis 再异步刷 PG，用户感知 ~0.5ms</li><li>粘性路由：按资源 × 用户 × 地点调度，资源利用率最大化</li><li>峰谷动态调整：凌晨缩实例省资源，晚高峰扩实例扛流量</li><li>从小到一台盒子到大到一百台机器，不换架构不改代码</li></ol>',9)])])}const _=i(r,[["render",l]]);export{c as __pageData,_ as default};
